function adjustStats(pl,changes){if(!pl.stats)pl.stats={welfare:50,education:50,freedom:50,safety:50};Object.entries(changes||{}).forEach(([k,v])=>{if(k in pl.stats)pl.stats[k]=Math.max(0,Math.min(100,pl.stats[k]+v));});}
function avgStats(pl){const a=pl.stats||{welfare:50,education:50,freedom:50,safety:50};return (a.welfare+a.education+a.freedom+a.safety)/4;}
function wealthScore(pl){const assetValue=pl.assets.reduce((n,i)=>n+(spaces[i].price||0),0);return Math.max(0,Math.min(100,Math.round((pl.money+assetValue)/30)));}
function finalScore(pl){return Math.round(wealthScore(pl)*.4+avgStats(pl)*.6);}
function closeModal(){if(modal)modal.remove();modal=null;}
function showModal(html){closeModal();const w=document.createElement('div');w.id='jadi-wni-modal';w.innerHTML='<div class="jmodalbox">'+html+'</div>';document.body.appendChild(w);modal=w;}
function head(k,t){return '<div class="flex items-center gap-3 mb-4 pb-3 border-b border-gray-700"><button class="jbtn" onclick="closeJadiWni()">← Keluar</button><div><div class="text-[9px] tracking-[.2em] text-red-300">'+k+'</div><h2 class="font-bold text-lg">'+t+'</h2></div></div>';}
function intro(){const p=gameRoot();p.innerHTML='<div class="jwni">'+head('ARSIP REPUBLIK · PERMAINAN STRATEGI','JADI WNI')+'<div class="paper p-4 mb-4"><div class="text-[9px] tracking-[.25em] red font-bold">MONOPOLI REPUBLIK: SUARA RAKYAT</div><h3 class="text-2xl font-black mt-2">SIAPA MENGUASAI<br>SUMBER DAYA?</h3><p class="text-xs mt-2">Bangun aset, hadapi kebijakan, dan rasakan perubahan kehidupan rakyat dalam lintasan sejarah 1965–2004.</p><div class="text-[10px] mt-3 border-t border-[#9b8a6d] pt-2">SIMULASI SEJARAH · 2–4 PEMAIN · SATU PERANGKAT</div><p class="text-[10px] mt-2">Setiap kebijakan akan menyebut nama pembuat atau pejabat/lembaga yang menetapkannya, berdasarkan sumber sejarah. Jika atribusinya tidak pasti, permainan akan menjelaskannya.</p></div><div class="grid grid-cols-2 gap-2 mb-4 text-xs"><div class="border border-gray-700 p-3">🎲 Dadu<p class="text-[10px] text-gray-400 mt-1">Bergerak mengitari papan.</p></div><div class="border border-gray-700 p-3">📜 Kartu peristiwa<p class="text-[10px] text-gray-400 mt-1">Dana Umum dan Kesempatan.</p></div><div class="border border-gray-700 p-3">🏛️ Aset rakyat<p class="text-[10px] text-gray-400 mt-1">Beli, miliki, dan pungut sewa.</p></div><div class="border border-gray-700 p-3">🗞️ Babak sejarah<p class="text-[10px] text-gray-400 mt-1">Kronologi membuka konteks.</p></div></div><p class="text-[10px] text-gray-500 mb-3">Harga, uang, sewa, dan efek kartu adalah mekanik fiktif permainan, bukan data ekonomi historis.</p><button class="jbtn w-full" onclick="jadiWniSetup()">MULAI PERMAINAN →</button></div>';}
window.closeJadiWni=function(){closeModal();document.getElementById('jadi-wni-game-shell')?.remove();const p=$('arena-play-panel'),l=$('arena-lobby-view');if(p){p.classList.add('hidden');p.innerHTML='';}if(l)l.classList.remove('hidden');};
window.playJadiWni=function(){css();$('arena-lobby-view')?.classList.add('hidden');const old=document.getElementById('jadi-wni-game-shell');old?.remove();const shell=document.createElement('div');shell.id='jadi-wni-game-shell';shell.innerHTML='<div class="jgamebox"><div id="jwni-game-content"></div></div>';document.body.appendChild(shell);intro();};
window.jadiWniSetup=function(){
 const opts=chars.map(c=>'<button type="button" class="char" data-char="'+c[0]+'" onclick="jadiWniToggleChar(this.dataset.char)">'+(characterImages[c[0]]?characterImage(c[0],'jchar-portrait'): '<div class="jchar-portrait jchar-fallback">'+c[2]+'</div>')+'<b>'+c[1]+'</b><small>'+c[3]+'</small><span id="pick-'+c[0]+'">Pilih karakter</span></button>').join('');
 game={selected:[],players:[],turn:0,round:1,phase:'setup',rolled:false,moving:false,lastDice:0,stepTile:-1,stepCount:0,log:'',lastPolicy:null};
 showModal('<div class="text-[9px] tracking-widest red font-bold">TAHAP 1 · PEMILIHAN RAKYAT</div><h3 class="text-xl font-black mt-1">Pilih pemain</h3><p class="text-xs mt-2 mb-3">Pilih 2–4 karakter. Karakter mewakili peran masyarakat, bukan tokoh politik.</p><div class="grid grid-cols-2 gap-2" id="jwni-char-grid">'+opts+'</div><div class="flex items-center justify-between mt-4"><span class="text-xs" id="jwni-selected-count">0 pemain dipilih</span><button class="jbtn" onclick="jadiWniStart()">Lanjut →</button></div>');
};
window.jadiWniToggleChar=function(id){if(!game||game.phase!=='setup')return;const i=game.selected.indexOf(id);if(i>=0)game.selected.splice(i,1);else if(game.selected.length<4)game.selected.push(id);chars.forEach(c=>{document.querySelector('[data-char="'+c[0]+'"]')?.classList.toggle('selected',game.selected.includes(c[0]));const t=$('pick-'+c[0]);if(t)t.textContent=game.selected.includes(c[0])?'✓ Dipilih':'Pilih karakter';});$('jwni-selected-count').textContent=game.selected.length+' pemain dipilih';};
window.jadiWniStart=function(){if(game.selected.length<2){alert('Pilih minimal 2 pemain.');return;}game.players=game.selected.map((id,index)=>{const c=chars.find(x=>x[0]===id);const colors=['#a52e38','#245b86','#4e7547','#95652d'];return{id,name:c[1],icon:c[2],color:colors[index],money:1500,pos:0,assets:[],skipTurns:0,stats:{welfare:50,education:50,freedom:50,safety:50}};});game.phase='play';game.turn=0;game.round=1;game.rolled=false;closeModal();render();chapterModal(0);};
function chapterModal(i){const c=chapters[i],img=chapterImages[i];showModal('<div class="text-[9px] tracking-widest red font-bold">ARSIP BABAK '+(i+1)+' / '+chapters.length+'</div>'+(img?'<img src="'+assetUrl(img)+'" alt="Ilustrasi '+esc(c[1])+'" class="jchapter-art">':'')+'<div class="text-3xl font-black mt-2">'+c[0]+'</div><h3 class="text-lg font-bold mt-1">'+c[1]+'</h3><p class="text-sm leading-relaxed mt-3">'+c[2]+'</p><p class="text-[10px] mt-4 opacity-60">Konteks sejarah ditampilkan kronologis dan tidak menentukan benar-salah pemain.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">LANJUT KE PAPAN</button>');}
window.closeJadiWniModal=closeModal;
function render(){
 const p=gameRoot();if(!p||!game)return;const pl=game.players[game.turn];
 const tiles=spaces.map((sp,i)=>{const owner=game.players.find(x=>x.assets.includes(i));const here=game.players.filter(x=>x.pos===i);const pos=i<6?[1,i+1]:i<10?[i-4,6]:i<16?[6,16-i]:[21-i,1];return '<div class="tile '+(owner?'owned ':'')+(here.length?'current ':'')+(game.stepTile===i?'pawn-step ':'')+(['fund','chance','tax','rest','start'].includes(sp.type)?'special':'')+'" data-kind="'+sp.type+'" data-group="'+esc(sp.group||'')+'" style="grid-row:'+pos[0]+';grid-column:'+pos[1]+'">'+tileImage(sp.name)+'<span class="ico">'+sp.icon+'</span><b>'+esc(sp.name)+'</b>'+(sp.price?'<small>'+money(sp.price)+'</small>':'')+(owner?'<small>MILIK: '+esc(owner.name)+'</small>':'')+'<span class="pawn-stack">'+here.map(x=>'<i class="pawn" title="'+esc(x.name)+'" style="--pawn-color:'+x.color+'">'+characterImage(x.id,'jpawn-image')+'</i>').join('')+'</span></div>';}).join('');
 const ranks=[...game.players].sort((a,b)=>b.money-a.money);
 p.innerHTML='<div class="jwni">'+head('MONOPOLI REPUBLIK · SUARA RAKYAT','JADI WNI')+'<div class="flex justify-between gap-2 mb-3 text-[10px]"><span class="text-red-200 font-bold">BABAK '+game.round+' / 12</span><span class="text-gray-400">Giliran: '+characterImage(pl.id,'jmini-portrait')+' '+esc(pl.name)+'</span></div><div class="board-scroll"><div class="board">'+tiles+'<div class="center"><div class="text-[9px] tracking-[.2em] text-red-300">REPUBLIK · PAPAN RAKYAT</div><div class="text-xl font-black mt-1">JADI WNI</div><p class="text-[10px] text-gray-400 mt-2">1965 — 2004 · Dadu menentukan langkah, keputusan menentukan nasib.</p><div class="text-[9px] text-yellow-100 mt-1">'+(game.lastPolicy?('DAMPAK TERAKHIR · '+esc(game.lastPolicy.title)):'KARTU SEJARAH DAPAT MENGUBAH SEMUA PEMAIN')+'</div><div class="dice-scene"><div class="dice-cube '+(game.moving?'rolling':'')+'">'+[1,2,3,4,5,6,7,8,9].map(n=>'<i class="pip" style="visibility:'+((game.lastDice===1&&n===5)||(game.lastDice===2&&(n===1||n===9))||(game.lastDice===3&&(n===1||n===5||n===9))||(game.lastDice===4&&(n===1||n===3||n===7||n===9))||(game.lastDice===5&&(n===1||n===3||n===5||n===7||n===9))||(game.lastDice===6&&(n===1||n===3||n===4||n===6||n===7||n===9))?'visible':'hidden')+'"></i>').join('')+'</div><div class="dice-info"><strong>'+(game.lastDice||'—')+'</strong><span>ANGKA DADU</span></div></div><div class="text-[10px] text-yellow-100 font-bold">'+(game.moving?'MELANGKAH '+game.stepCount+' / '+game.lastDice+' PETAK':' '+(game.lastDice?'TOTAL '+game.lastDice+' LANGKAH':'LEMPAR DADU UNTUK MULAI'))+'</div><div class="grid grid-cols-2 gap-2 mt-3 text-left">'+ranks.map(x=>'<div class="text-[10px] border border-gray-700 p-2">'+characterImage(x.id,'jrank-portrait')+' '+esc(x.name)+'<b class="block text-yellow-100">'+money(x.money)+'</b></div>').join('')+'</div></div></div></div><div class="grid grid-cols-2 gap-2 mt-3"><div class="border border-gray-700 p-3"><div class="text-[9px] text-gray-500">PEMAIN AKTIF</div><b>'+esc(pl.name)+'</b><div class="text-xl font-black text-yellow-100">'+money(pl.money)+'</div><div class="text-[10px] text-gray-500">Aset: '+pl.assets.length+'</div></div><div class="border border-gray-700 p-3"><div class="text-[9px] text-gray-500">POSISI</div><b>'+esc(spaces[pl.pos].name)+'</b><div class="text-[10px] text-gray-400 mt-1">Petak '+(pl.pos+1)+' dari '+spaces.length+'</div></div></div><div class="grid grid-cols-4 gap-1 mt-2 text-center">'+[['Kesejahteraan','welfare'],['Pendidikan','education'],['Kebebasan','freedom'],['Keselamatan','safety']].map(([label,key])=>'<div class="border border-gray-800 rounded p-1"><div class="text-[8px] text-gray-500">'+label+'</div><b class="text-xs text-yellow-100">'+(pl.stats?.[key]??50)+'</b><div class="h-1 bg-gray-700 mt-1"><div class="h-1 bg-emerald-500" style="width:'+(pl.stats?.[key]??50)+'%"></div></div></div>').join('')+'</div><div class="flex gap-2 mt-3"><button class="jbtn flex-1" onclick="jadiWniRoll()" '+(game.rolled?'disabled':'')+'>🎲 LEMPAR DADU</button><button class="jbtn flex-1" onclick="jadiWniEndTurn()" '+(!game.rolled||game.moving?'disabled':'')+'>AKHIRI GILIRAN →</button></div><div class="grid grid-cols-2 gap-2 mt-2"><button class="jbtn" onclick="jadiWniShowChapter()">📜 Baca babak sejarah</button><button class="jbtn" onclick="jadiWniRules()">ⓘ Aturan permainan</button><button class="jbtn col-span-2" onclick="jadiWniArchive()">🗂️ Buka arsip tokoh</button></div><div class="text-[10px] text-gray-400 mt-3 border-t border-gray-800 pt-3">'+esc(game.log||'Permainan dimulai. Lempar dadu untuk bergerak.')+'</div></div>';
}
window.jadiWniRules=function(){showModal('<div class="text-[9px] red font-bold">PETUNJUK BERMAIN</div><h3 class="text-xl font-black mt-1">Aturan singkat</h3><ol class="list-decimal pl-5 text-sm space-y-2 mt-3"><li>2–4 pemain bergiliran melempar dadu.</li><li>Di aset kosong, pemain boleh membeli. Jika milik pemain lain, bayar sewa.</li><li>Petak Tahanan hanya tempat berkunjung; kartu Kesempatan tertentu dapat mengirim pemain ke sana dan membuatnya melewatkan satu giliran.</li><li>Dana Umum dan Kesempatan mengambil kartu peristiwa. Pajak mengurangi uang.</li><li>Melewati MULAI memberi Rp100.</li><li>Permainan berlangsung tepat 12 putaran penuh. Tidak ada eliminasi otomatis karena uang habis.</li><li>Skor akhir menggabungkan kekayaan (40%) dan rata-rata empat indikator kehidupan rakyat (60%): kesejahteraan, pendidikan, kebebasan, dan keselamatan.</li><li>Kartu dan peristiwa dapat mengubah indikator. Nilainya dibatasi 0–100.</li></ol><p class="text-[10px] mt-3 opacity-70">Harga, uang awal, sewa, dan efek kartu adalah angka simulasi gameplay.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">MENGERTI</button>');};
window.jadiWniShowChapter=function(){const i=Math.min(chapters.length-1,Math.floor((game.round-1)/2));chapterModal(i);};
window.jadiWniArchive=function(){const entries=archivePeople.map(([file,name,desc])=>{const related=historyCards.filter(h=>h.person===name);const portrait=file?'<img src="'+assetUrl('tokoh/'+file)+'" alt="'+esc(name)+'" class="w-20 h-24 object-contain shrink-0 bg-[#e9dfc7]">':'<div class="w-20 h-24 shrink-0 flex items-center justify-center text-3xl bg-[#e9dfc7]">📜</div>';return '<div class="flex gap-3 border-b border-[#b8a98d] py-3">'+portrait+'<div class="min-w-0 flex-1"><b class="text-sm">'+esc(name)+'</b><p class="text-xs leading-relaxed mt-1">'+esc(desc)+'</p>'+(related.length?related.map(h=>'<div class="mt-2 rounded bg-[#d8c9a8] p-2"><div class="text-[9px] font-bold text-[#8b2635]">'+esc(h.year)+' · KARTU PERISTIWA</div><b class="text-xs">'+esc(h.title)+'</b><p class="text-[10px] leading-relaxed mt-1">'+esc(h.effect)+'</p><p class="text-[9px] leading-relaxed mt-1"><b>Atribusi:</b> '+esc(h.attribution)+'</p><a href="'+h.source+'" target="_blank" rel="noopener" class="text-[9px] underline mt-1 inline-block">Sumber: '+esc(h.sourceLabel)+'</a></div>').join(''):'<p class="text-[10px] mt-2 opacity-70">Arsip latar; belum memiliki kartu dampak langsung pada papan.</p>')+'</div></div>';}).join('');showModal('<div class="text-[9px] red font-bold tracking-widest">DOKUMEN · PERJUANGAN · KEBIJAKAN</div><h3 class="text-xl font-black mt-1">Arsip Tokoh & Dampak Papan</h3><p class="text-[10px] mt-2">Setiap kartu mencantumkan konteks, pihak yang berperan, efek simulasi, dan sumber. Dampak angka adalah mekanik permainan, bukan data historis.</p><div class="mt-2">'+entries+'</div><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">KEMBALI KE PAPAN</button>');};
window.jadiWniRoll=async function(){if(!game||game.rolled||game.moving)return;const pl=game.players[game.turn],dice=1+Math.floor(Math.random()*6);game.rolled=true;game.moving=true;game.lastDice=dice;game.stepCount=0;game.log=pl.name+' mendapatkan angka '+dice+'. Pion bergerak mengikuti jalur papan.';render();for(let step=0;step<dice;step++){await new Promise(r=>setTimeout(r,300));const previous=pl.pos;pl.pos=(pl.pos+1)%spaces.length;if(previous===spaces.length-1)pl.money+=100;game.stepTile=pl.pos;game.stepCount=step+1;render();}await new Promise(r=>setTimeout(r,180));game.moving=false;game.log=pl.name+' melempar dadu '+dice+' dan berjalan '+dice+' langkah menuju '+spaces[pl.pos].name+'.';render();resolve();};
function drawChallengeCard(pl){const h=challengeCards[Math.floor(Math.random()*challengeCards.length)];const portraitFiles={'D.N. Aidit':'dn aidit.jpg','Tan Malaka':'tan malaka.jpg','Siti Hartinah (Tien Soeharto)':'tien soeharto.jpg','Marsinah':'marsinah.jpg','Wiji Thukul':'widji thukul.jpg','Munir Said Thalib':'munir.jpg','Prabowo Subianto':'prabowo.jpg'};const file=portraitFiles[h.person];const portrait=file?'<div class="jchallenge-portrait-wrap"><img class="jchallenge-portrait" src="'+assetUrl('tokoh/'+file)+'" alt="Potret '+esc(h.person)+'" loading="eager" decoding="async" onerror="this.parentElement.innerHTML=\'<div class=&quot;jchallenge-portrait-fallback&quot;>Gambar '+esc(h.person)+' tidak ditemukan: '+esc(file)+'</div>\'"></div>':'';game.activeChallenge={playerId:pl.id,card:h};showModal('<div class="text-[9px] red font-bold tracking-widest">🃏 KARTU CHALLENGE SEJARAH · '+esc(h.year)+'</div>'+portrait+'<h3 class="text-xl font-black mt-2">'+esc(h.title)+'</h3><div class="text-xs font-bold mt-1">TOKOH: '+esc(h.person)+'</div><p class="text-sm leading-relaxed mt-3">'+esc(h.question)+'</p><div class="grid gap-2 mt-4">'+h.options.map((option,i)=>'<button class="jbtn w-full text-left" onclick="jadiWniAnswerChallenge('+i+')">'+String.fromCharCode(65+i)+'. '+esc(option)+'</button>').join('')+'</div><p class="text-[9px] opacity-60 mt-3">Jawab tantangan untuk menentukan dampak pada indikator kehidupan rakyatmu.</p>');}
window.jadiWniAnswerChallenge=function(choice){if(!game?.activeChallenge)return;const {playerId,card}=game.activeChallenge,pl=game.players.find(p=>p.id===playerId);if(!pl)return;const correct=choice===card.answer;if(correct){adjustStats(pl,card.successStats);pl.money+=50;game.log='Challenge benar: '+card.person+'. '+card.success;}else{adjustStats(pl,card.failStats);pl.money=Math.max(0,pl.money-30);game.log='Challenge belum tepat: '+card.person+'. '+card.fail;}game.lastPolicy={title:card.title};game.activeChallenge=null;render();showModal('<div class="text-[9px] red font-bold tracking-widest">HASIL CHALLENGE · '+(correct?'BERHASIL':'BELUM TEPAT')+'</div><h3 class="text-xl font-black mt-2">'+(correct?'🎖️ Jawaban benar!':'📜 Coba pelajari lagi')+'</h3><div class="text-xs font-bold mt-2">'+esc(card.person)+' · '+esc(card.year)+'</div><p class="text-sm mt-3">'+esc(correct?card.success:card.fail)+'</p><p class="text-xs mt-3 font-bold">'+(correct?'Bonus +Rp50 dan indikator bertambah.':'Konsekuensi −Rp30 dan indikator berkurang.')+'</p><p class="text-[9px] opacity-60 mt-3">Dampak uang dan indikator adalah mekanik simulasi permainan.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">LANJUT</button>');};
function applyHistoricalCard(pl,h){game.players.forEach(player=>adjustStats(player,h.stats));if(h.jailTurns){pl.pos=10;pl.skipTurns=Math.max(pl.skipTurns||0,h.jailTurns);}game.lastPolicy=h;game.log='Kartu sejarah: '+h.title+'. '+h.effect;render();showModal('<div class="text-[9px] red font-bold tracking-widest">KARTU SEJARAH · '+esc(h.year)+'</div><h3 class="text-xl font-black mt-2">'+esc(h.title)+'</h3><div class="text-xs font-bold mt-1">TOKOH: '+esc(h.person)+'</div><p class="text-sm leading-relaxed mt-3">'+esc(h.history)+'</p><div class="mt-3 p-3 bg-[#d8c9a8] rounded"><div class="text-[9px] font-bold text-[#8b2635]">DAMPAK KE SELURUH PAPAN</div><p class="text-xs mt-1">'+esc(h.effect)+'</p>'+(h.jailTurns?'<p class="text-xs font-bold text-red-800 mt-2">🚔 '+esc(pl.name)+' MASUK TAHANAN · '+h.jailTurns+' GILIRAN</p>':'')+'</div><p class="text-[9px] leading-relaxed mt-3"><b>Atribusi:</b> '+esc(h.attribution)+'</p><a href="'+h.source+'" target="_blank" rel="noopener" class="text-[10px] underline mt-2 inline-block">Baca sumber: '+esc(h.sourceLabel)+'</a><p class="text-[9px] opacity-60 mt-3">Seluruh perubahan angka adalah simulasi gameplay, bukan ukuran dampak historis.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">LANJUT</button>');}
function resolve(){const pl=game.players[game.turn],sp=spaces[pl.pos];if(sp.type==='asset'){const owner=game.players.find(x=>x.assets.includes(pl.pos));if(!owner){showModal('<div class="text-[9px] red font-bold">KEPUTUSAN EKONOMI</div><h3 class="text-xl font-black mt-1">'+sp.icon+' '+sp.name+'</h3><p class="text-sm mt-2">Harga: <b>'+money(sp.price)+'</b>. Sewa dasar: '+money(sp.rent)+'.</p><p class="text-xs mt-2">Apakah kamu ingin membeli aset ini?</p><div class="flex gap-2 mt-4"><button class="jbtn flex-1" onclick="jadiWniBuy()">BELI</button><button class="jbtn flex-1" onclick="closeJadiWniModal()">LEWATI</button></div>');}else if(owner!==pl){pl.money-=sp.rent;owner.money+=sp.rent;adjustStats(pl,{welfare:-2});game.log+=' Membayar sewa '+money(sp.rent)+' kepada '+owner.name+'.';info('SEWA DIBAYAR',sp.name,'Kamu membayar '+money(sp.rent)+' kepada '+owner.name+'.');}else info('ASET MILIKMU',sp.name,'Kamu berhenti di aset yang sudah kamu miliki.');}
 else if(sp.type==='tax'){pl.money-=sp.amount;adjustStats(pl,{welfare:-5});info('KEWAJIBAN PUBLIK',sp.name,'Kamu membayar '+money(sp.amount)+' ke kas simulasi.');}
 else if(sp.type==='jail'){info('TAHANAN','Hanya berkunjung','Kamu berada di petak Tahanan sebagai pengunjung. Tidak ada giliran yang hilang.');}
 else if(sp.type==='challenge'){drawChallengeCard(pl);return;}
 else if(sp.type==='fund'||sp.type==='chance'){const pool=cards.filter(c=>c[0]===sp.type),c=pool[Math.floor(Math.random()*pool.length)];if(c[4]==='jail'){pl.pos=10;pl.skipTurns=1;game.log+=' Mendapat kartu penahanan dan dikirim ke Tahanan.';}else pl.money+=c[3];adjustStats(pl,c[5]);showModal('<div class="text-[9px] '+(sp.type==='fund'?'blue':'red')+' font-bold">'+(sp.type==='fund'?'DANA UMUM · BIRU':'KESEMPATAN · MERAH')+'</div><img src="'+assetUrl(sp.type==='fund'?'kartu/dana-umum/dana umum.jpg':'kartu/kesempatan/kesempatan.jpg')+'" alt="Kartu '+(sp.type==='fund'?'Dana Umum':'Kesempatan')+'" class="jcard-art"><h3 class="text-xl font-black mt-2">'+c[1]+'</h3><p class="text-sm leading-relaxed mt-3">'+c[2]+'</p>'+(c[4]==='jail'?'<div class="text-xl font-black mt-4 text-red-800">🚔 MASUK TAHANAN</div>':'<div class="text-2xl font-black mt-4 '+(c[3]>=0?'text-green-800':'text-red-800')+'">'+(c[3]>=0?'+':'−')+money(Math.abs(c[3]))+'</div>')+'<p class="text-[9px] mt-1 opacity-60">Kartu simulasi permainan; bukan kutipan dokumen sejarah.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">LANJUT</button>');}
 else if(sp.type==='rest')info('RUANG PUBLIK',sp.name,'Tidak ada transaksi. Kamu dapat beristirahat sejenak.');else info('GARIS MULAI','Upah rakyat','Kamu menerima Rp100 saat melewati petak MULAI.');}
window.jadiWniBuy=function(){const pl=game.players[game.turn],sp=spaces[pl.pos];if(pl.money>=sp.price){pl.money-=sp.price;pl.assets.push(pl.pos);game.log+=' Membeli '+sp.name+'.';}else game.log+=' Uang tidak cukup untuk membeli '+sp.name+'.';closeModal();render();};
function info(k,t,d){showModal('<div class="text-[9px] red font-bold">'+k+'</div><h3 class="text-xl font-black mt-2">'+t+'</h3><p class="text-sm mt-3">'+d+'</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">LANJUT</button>');}
window.jadiWniEndTurn=function(){if(!game||!game.rolled||game.moving)return;closeModal();game.turn++;if(game.turn>=game.players.length){game.turn=0;game.round++;}game.rolled=false;if(game.round>12){finish();return;}const next=game.players[game.turn];if(next.skipTurns>0){next.skipTurns--;game.rolled=true;game.log=next.name+' harus melewatkan satu giliran karena berada di Tahanan.';render();showModal('<div class="text-[9px] red font-bold">GILIRAN DILEWATI</div><h3 class="text-xl font-black mt-2">🚔 Tahanan</h3><p class="text-sm mt-3">'+esc(next.name)+' harus melewatkan giliran ini. Setelah itu permainan berlanjut seperti biasa.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal();jadiWniEndTurn()">LEWATI GILIRAN →</button>');return;}render();if(game.round>1&&game.round%2===1)chapterModal(Math.min(chapters.length-1,Math.floor((game.round-1)/2)));};
function finish(){game.phase='finished';const scores=game.players.map(pl=>({pl,total:finalScore(pl),wealth:wealthScore(pl),life:Math.round(avgStats(pl))})).sort((a,b)=>b.total-a.total),w=scores[0],score=w.total,p=gameRoot();p.innerHTML='<div class="jwni">'+head('HASIL AKHIR · REPUBLIK','PERMAINAN SELESAI')+'<div class="paper p-4 text-center"><div class="text-4xl">🏆</div><div class="text-[9px] red tracking-widest font-bold mt-2">PEMENANG JADI WNI</div><h3 class="text-2xl font-black mt-1">'+esc(w.pl.name)+' '+w.pl.icon+'</h3><div class="text-2xl font-black mt-2">'+w.total+' / 100 POIN</div><p class="text-[10px] mt-1">Kekayaan '+w.wealth+'/100 · Kehidupan rakyat '+w.life+'/100</p></div><h4 class="font-bold mt-4 mb-2">Klasemen permainan</h4>'+scores.map((x,i)=>'<div class="border-b border-gray-700 py-2 text-xs"><div class="flex justify-between"><span>'+(i+1)+'. '+x.pl.icon+' '+esc(x.pl.name)+'</span><b>'+x.total+' poin</b></div><div class="text-[9px] text-gray-400 mt-1">Kekayaan '+x.wealth+' · Kesejahteraan '+x.pl.stats.welfare+' · Pendidikan '+x.pl.stats.education+' · Kebebasan '+x.pl.stats.freedom+' · Keselamatan '+x.pl.stats.safety+'</div></div>').join('')+'<p class="text-[10px] text-gray-500 mt-3">Skor akhir: 40% kekayaan dan 60% rata-rata indikator kehidupan. Sesi permainan tidak disimpan; hanya skor pemenang dikirim ke klasemen jika login.</p><button class="jbtn w-full mt-4" onclick="jadiWniSaveScore('+score+')">SIMPAN SKOR</button><button class="jbtn w-full mt-2" onclick="jadiWniEpilogue()">LIHAT BABAK BERIKUTNYA →</button><button class="jbtn w-full mt-2" onclick="jadiWniRestart()">MAIN LAGI</button></div>';}
window.jadiWniSaveScore=async function(score){const root=gameRoot();const btn=root?.querySelector('button[onclick^="jadiWniSaveScore"]');if(btn)btn.disabled=true;let msg='Skor sesi selesai.';try{if(typeof activeUser!=='undefined'&&activeUser?.id&&typeof supabaseClient!=='undefined'){const {error}=await supabaseClient.from('ghoustory_arena_results').insert({user_id:activeUser.id,game_mode:'jadi_wni',score,details:{}});if(error)throw error;if(typeof refreshArena==='function')await refreshArena();msg='Skor pemenang tersimpan di klasemen Arena Gaib.';}else msg='Kamu belum login; skor sesi tidak dikirim ke klasemen.';}catch(e){console.warn('JADI WNI score save:',e);msg='Skor belum tersimpan ke klasemen: '+(e.message||'koneksi bermasalah');}const box=root?.querySelector('.jwni');const note=document.createElement('p');note.className='text-xs text-center mt-3 text-gray-300';note.textContent=msg;box?.appendChild(note);if(btn)btn.textContent='SKOR DIPROSES';};
window.jadiWniEpilogue=function(){showModal('<div class="text-[9px] tracking-widest red font-bold">EPILOG · 20 OKTOBER 2024</div><img src="'+assetUrl('peristiwa/2024 — Babak Berikutnya.jpg')+'" alt="Babak berikutnya" class="jepilogue-art"><h3 class="text-2xl font-black mt-2">PLOT TWIST: REPUBLIK LANJUT LAGI.</h3><p class="text-sm leading-relaxed mt-3">Setelah 12 ronde, kalian melewati krisis, kebijakan, protes, dan Reformasi. Soeharto mengundurkan diri pada 21 Mei 1998. Dua puluh enam tahun kemudian, Prabowo Subianto dilantik sebagai Presiden Republik Indonesia pada 20 Oktober 2024.</p><p class="text-sm font-bold mt-3">Lho... babak berikutnya dipimpin Pra...bo.... 😶</p><p class="text-sm mt-2">Pemimpin berganti, tetapi pertanyaan untuk rakyat tetap sama: apakah kehidupan benar-benar berubah?</p><p class="text-[9px] mt-3">Fakta pelantikan: <a href="https://setneg.go.id/baca/index/prabowo_subianto_dan_gibran_rakabuming_raka_resmi_dilantik_sebagai_presiden_dan_wakil_presiden_republik_indonesia" target="_blank" rel="noopener" style="text-decoration:underline">Sekretariat Negara RI, 20 Oktober 2024</a>.</p><button class="jbtn w-full mt-4" onclick="closeJadiWniModal()">TUTUP EPILOG</button>');};
window.jadiWniRestart=function(){closeModal();game=null;intro();};
const original=window.playArena;window.playArena=function(mode){if(mode==='jadi_wni'){playJadiWni();return;}return original.apply(this,arguments);};
css();
